content.text:
{
  "primary_meaning": "A true believer whose heart is circumcised by the Spirit (an inward Jew) rather than an ethnic descendant of Abraham alone",
  "primary_basis": [
    "Romans 2:28-29",
    "Romans 9:6-8",
    "Philippians 3:3",
    "Galatians 3:7; 6:15-16"
  ],
  "alternatives": [
    {
      "meaning": "Literal ethnic or religious member of the Jewish people (the ordinary narrative and historical sense)",
      "basis": [
        "OT historical books and prophets",
        "Gospels and Acts narratives (e.g., John 4:9; Acts 2:5)",
        "Paul’s self-identification (Romans 11:1; Philippians 3:5)"
      ],
      "prominence": "dominant"
    },
    {
      "meaning": "Those who claim Jewish identity yet oppose Christ and are regarded as false claimants (synagogue of Satan)",
      "basis": [
        "Revelation 2:9",
        "Revelation 3:9"
      ],
      "prominence": "minority"
    },
    {
      "meaning": "The Jewish people corporately as representatives of unbelief or rejection of the Messiah in contrast to the Church",
      "basis": [
        "John 8:39-47",
        "Acts 13:45-46",
        "1 Thessalonians 2:14-16",
        "historical supersessionist readings of Romans 9–11"
      ],
      "prominence": "common"
    }
  ],
  "has_settled_consensus": false,
  "confidence": "medium",
  "notes": "In Christian interpretation the term functions primarily as an ethnic/religious designation; the spiritualized Pauline sense is widely taught but remains secondary and is not a universal symbolic consensus. Other readings arise from specific polemical or prophetic contexts and vary by tradition."
}
